// ErpIntegrationServiceServer is the server API for ErpIntegrationService service.
// All implementations must embed UnimplementedErpIntegrationServiceServer
// for forward compatibility.
//
// ErpIntegrationService orchestrates the ERP standard-cost integration pipeline.
type ErpIntegrationServiceServer interface {
	// CreateErpBatch creates a batch for a period (refused if one is in flight).
	// Permission: finance.cost.erpintegration.trigger
	CreateErpBatch(context.Context, *CreateErpBatchRequest) (*CreateErpBatchResponse, error)
	// ListErpBatches lists batches filtered by period/status.
	// Permission: finance.cost.erpintegration.view
	ListErpBatches(context.Context, *ListErpBatchesRequest) (*ListErpBatchesResponse, error)
	// GetErpBatch returns a batch with summary, progress and allowed actions.
	// Permission: finance.cost.erpintegration.view
	GetErpBatch(context.Context, *GetErpBatchRequest) (*GetErpBatchResponse, error)
	// AbandonErpBatch moves a batch to FAILED (PG only).
	// Permission: finance.cost.erpintegration.trigger
	AbandonErpBatch(context.Context, *AbandonErpBatchRequest) (*AbandonErpBatchResponse, error)
	// LoadErpDemand loads ERP demand rows (read-only Oracle).
	// Permission: finance.cost.erpintegration.trigger
	LoadErpDemand(context.Context, *LoadErpDemandRequest) (*LoadErpDemandResponse, error)
	// RunErpCoverage computes mapping/cost coverage.
	// Permission: finance.cost.erpintegration.trigger
	RunErpCoverage(context.Context, *RunErpCoverageRequest) (*RunErpCoverageResponse, error)
	// RunErpDerive derives standard costs (G10).
	// Permission: finance.cost.erpintegration.trigger
	RunErpDerive(context.Context, *RunErpDeriveRequest) (*RunErpDeriveResponse, error)
	// ValidateErpBatch runs pre-push validations.
	// Permission: finance.cost.erpintegration.validate
	ValidateErpBatch(context.Context, *ValidateErpBatchRequest) (*ValidateErpBatchResponse, error)
	// ReconErpBatch reconciles against the Oracle adjustment set (read-only).
	// Permission: finance.cost.erpintegration.trigger
	ReconErpBatch(context.Context, *ReconErpBatchRequest) (*ReconErpBatchResponse, error)
	// ListErpCoverage lists coverage lines.
	// Permission: finance.cost.erpintegration.view
	ListErpCoverage(context.Context, *ListErpCoverageRequest) (*ListErpCoverageResponse, error)
	// ExportErpCoverage exports coverage as xlsx.
	// Permission: finance.cost.erpintegration.export
	ExportErpCoverage(context.Context, *ExportErpCoverageRequest) (*ExportErpCoverageResponse, error)
	// ExportErpRecon exports the recon outcome of a batch as xlsx.
	// Permission: finance.cost.erpintegration.export
	ExportErpRecon(context.Context, *ExportErpReconRequest) (*ExportErpReconResponse, error)
	// AckErpWarnings acknowledges validation warnings (audit ERP_WARN_ACK).
	// Permission: finance.cost.erpintegration.approve
	AckErpWarnings(context.Context, *AckErpWarningsRequest) (*AckErpWarningsResponse, error)
	// ListErpStdCost lists derived standard cost rows.
	// Permission: finance.cost.erpintegration.view
	ListErpStdCost(context.Context, *ListErpStdCostRequest) (*ListErpStdCostResponse, error)
	// PreviewErpPush returns control totals, row count and hash (no Oracle I/O).
	// Permission: finance.cost.erpintegration.push
	PreviewErpPush(context.Context, *PreviewErpPushRequest) (*PreviewErpPushResponse, error)
	// PushErpBatch pushes the batch to Oracle (flag push_enabled).
	// Permission: finance.cost.erpintegration.push
	PushErpBatch(context.Context, *PushErpBatchRequest) (*PushErpBatchResponse, error)
	// PreviewErpAdjOperation snapshots and previews an ADJ operation (read-only Oracle).
	// Permission: finance.cost.erpintegration.valuate / .approve / .restore per operation
	PreviewErpAdjOperation(context.Context, *PreviewErpAdjOperationRequest) (*PreviewErpAdjOperationResponse, error)
	// GetErpAdjPreview returns totals, excluded count, the V-07 result and a paged head list.
	// Permission: finance.cost.erpintegration.view, or .valuate / .approve / .restore per operation
	GetErpAdjPreview(context.Context, *GetErpAdjPreviewRequest) (*GetErpAdjPreviewResponse, error)
	// ExecuteErpAdjOperation executes a previewed ADJ operation (gates G1-G11).
	// Permission: finance.cost.erpintegration.valuate / .approve / .restore per operation
	ExecuteErpAdjOperation(context.Context, *ExecuteErpAdjOperationRequest) (*ExecuteErpAdjOperationResponse, error)
	// LockErpBatch locks the batch (LOCK_BATCH single call).
	// Permission: finance.cost.erpintegration.lock
	LockErpBatch(context.Context, *LockErpBatchRequest) (*LockErpBatchResponse, error)
	// ListErpOracleCalls returns the Oracle call audit log.
	// Permission: finance.cost.erpintegration.view
	ListErpOracleCalls(context.Context, *ListErpOracleCallsRequest) (*ListErpOracleCallsResponse, error)
	// LockErpPeriod locks a period.
	// Permission: finance.cost.erpintegration.lock
	LockErpPeriod(context.Context, *LockErpPeriodRequest) (*LockErpPeriodResponse, error)
	// UnlockErpPeriod unlocks a period.
	// Permission: finance.cost.erpintegration.unlock
	UnlockErpPeriod(context.Context, *UnlockErpPeriodRequest) (*UnlockErpPeriodResponse, error)
	// GetErpPeriodLock returns the period lock state (used by the orchestrator cron).
	// Permission: finance.cost.erpintegration.view
	GetErpPeriodLock(context.Context, *GetErpPeriodLockRequest) (*GetErpPeriodLockResponse, error)
	// LinkErpToProduct links an ERP item to a product (V-04/V-06/V-11/V-12; never writes grade codes).
	// Permission: finance.cost.erpintegration.update
	LinkErpToProduct(context.Context, *LinkErpToProductRequest) (*LinkErpToProductResponse, error)
	// CreateCostProductFromDemand creates a Yarn product from a demand line (MB is FailedPrecondition).
	// Permission: finance.cost.erpintegration.update + existing product-master create
	CreateCostProductFromDemand(context.Context, *CreateCostProductFromDemandRequest) (*CreateCostProductFromDemandResponse, error)
	// GetErpItemLinkReport reports duplicate, unlinked and no-fg_type items.
	// Permission: finance.cost.erpintegration.view
	GetErpItemLinkReport(context.Context, *GetErpItemLinkReportRequest) (*GetErpItemLinkReportResponse, error)
	// RunErpAttributeBackfill backfills empty attributes on linked products (dry_run default true).
	// Permission: finance.cost.erpintegration.update
	RunErpAttributeBackfill(context.Context, *RunErpAttributeBackfillRequest) (*RunErpAttributeBackfillResponse, error)
	// RunErpMasterSync syncs OM_ITEM / OM_GRADE_CODE_1 into replicas (read-only Oracle).
	// Permission: finance.cost.erpintegration.sync
	RunErpMasterSync(context.Context, *RunErpMasterSyncRequest) (*RunErpMasterSyncResponse, error)
	// ExportErpManualSample exports a stratified manual check sample (>=30 combos).
	// Permission: finance.cost.erpintegration.export
	ExportErpManualSample(context.Context, *ExportErpManualSampleRequest) (*ExportErpManualSampleResponse, error)
	// GetErpCurrencySanity returns currency rate sanity checks for a period.
	// Permission: finance.cost.erpintegration.view
	GetErpCurrencySanity(context.Context, *GetErpCurrencySanityRequest) (*GetErpCurrencySanityResponse, error)
	// GetErpIntegrationConfig returns flags, writer mode and Oracle IF configured (never secrets).
	// Permission: finance.cost.erpintegration.view
	GetErpIntegrationConfig(context.Context, *GetErpIntegrationConfigRequest) (*GetErpIntegrationConfigResponse, error)
	// GetErpIntegrationSchedule returns the effective schedule and next run.
	// Permission: finance.cost.erpintegration.view
	GetErpIntegrationSchedule(context.Context, *GetErpIntegrationScheduleRequest) (*GetErpIntegrationScheduleResponse, error)
	// UpdateErpIntegrationSchedule edits the settings-row schedule (cron validated server-side).
	// Permission: finance.cost.erpintegration.update
	UpdateErpIntegrationSchedule(context.Context, *UpdateErpIntegrationScheduleRequest) (*UpdateErpIntegrationScheduleResponse, error)
	// RunErpBacktest runs a SHADOW batch for a closed period.
	// Permission: finance.cost.erpintegration.trigger
	RunErpBacktest(context.Context, *RunErpBacktestRequest) (*RunErpBacktestResponse, error)
	// GetErpBacktestReport returns the per-period diff report.
	// Permission: finance.cost.erpintegration.view + finance.cost.erpintegration.export
	GetErpBacktestReport(context.Context, *GetErpBacktestReportRequest) (*GetErpBacktestReportResponse, error)
	mustEmbedUnimplementedErpIntegrationServiceServer()
}

